CREATE OR REPLACE FUNCTION public.contact_request_inbox() RETURNS TABLE(id uuid,requester_id uuid,requester_name text,project_title text,kind text,target_name text,message text,state text,reason text,admin_question text,introduced_at timestamptz,created_at timestamptz,referral_position text,previous_requests bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
SELECT c.id,c.requester_id,coalesce(nullif(btrim(concat_ws(' ',u.first_name,u.last_name)),''),'Member'),p.title,c.kind,coalesce(f.name,a.name,'Target unavailable'),c.message,c.state,c.reason,c.admin_question,c.introduced_at,c.created_at,CASE WHEN c.kind='advisor' THEN a.referral_position ELSE 'No platform fee on public funding' END,(SELECT count(*) FROM public.contact_request prior WHERE prior.requester_id=c.requester_id AND prior.created_at<c.created_at)
FROM public.contact_request c JOIN public.project p ON p.id=c.project_id LEFT JOIN public.user_profile u ON u.user_id=c.requester_id LEFT JOIN public.funding_programme f ON c.kind='funding' AND f.id=c.target_id LEFT JOIN public.advisor a ON c.kind='advisor' AND a.id=c.target_id WHERE private.has_role(auth.uid(),'admin') ORDER BY c.created_at;
$$;
REVOKE ALL ON FUNCTION public.contact_request_inbox() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.contact_request_inbox() TO authenticated;